import{glucoseState,temperatureState}from './endo-models.js?v=20261023-physicscomplete01';
export function buildEndo(g,T,w={}){const mat=c=>new T.MeshStandardMaterial({color:c,roughness:.42}),ball=(p,s,c,name)=>{let m=new T.Mesh(new T.SphereGeometry(1,32,24),mat(c));m.position.set(...p);m.scale.set(...s);m.name=name;g.add(m);return m;},tube=(points,r,c,name)=>{let curve=new T.CatmullRomCurve3(points.map(p=>new T.Vector3(...p))),m=new T.Mesh(new T.TubeGeometry(curve,64,r,14,false),mat(c));m.name=name;g.add(m);};
if(w.kind==='temperature'){let f=temperatureState(w.state||'hot'),skin=new T.Mesh(new T.BoxGeometry(3.7,.22,1.7),mat(0xc89b8d));skin.position.y=.55;skin.name='skin-surface';g.add(skin);tube([[-1.4,-.7,0],[-1.4,.1,0],[-.8,.27,0],[.7,.27,0],[1.4,.1,0],[1.4,-.7,0]],f.dilated?.11:.05,0xbf7d7e,'skin-blood-vessel');let pts=[];for(let i=0;i<=70;i++){let a=i*.35;pts.push([-.6+.22*Math.cos(a),-.45+.018*i,.22*Math.sin(a)+.45]);}tube(pts,.035,0xe1c69f,'sweat-duct-coil');if(f.sweat)for(let i=0;i<4;i++)ball([-.6,.9+i*.12,.5],[.06,.09,.06],0xb9d5dc,'sweat');for(let i=0;i<3;i++)tube([[-.1,-1+i*.12,0],[.5,-.95+i*.12,.2],[1.3,-1+i*.12,0]],.055,0xcaa19a,'skeletal-muscle');return;}
let mode=w.kind==='glucagon'?'glucagon':'insulin',f=glucoseState({mode,progress:w.progress??.5,active:w.state!=='absent'});ball([1,0,0],[.9,.85,.65],0xbb8880,'target-cells');tube([[-1.3,-1.05,0],[-1.3,0,0],[-1.3,1.05,0]],.38,0x507288,'blood-vessel');for(let i=0;i<f.blood;i++)ball([-1.3+(i%2)*.16,-.8+Math.floor(i/2)*.45,.35],[.07,.07,.07],0xecc28e,'blood-glucose');for(let i=0;i<f.store;i++){let x=.5+(i%4)*.28,y=-.3+Math.floor(i/4)*.4;ball([x,y,.6],[.075,.075,.075],0xecc28e,'glycogen-unit');if(i%4)tube([[x-.28,y,.6],[x,y,.6]],.025,0xbad1ca,'glycogen-link');}if(f.inTransit)ball([mode==='glucagon'?.5-f.fraction:-.5+f.fraction,0,.45],[.075,.075,.075],0xecc28e,'transferring-glucose');let hormone=new T.Mesh(new T.OctahedronGeometry(.15),mat(0xa6cbce));hormone.position.set(-.3,.7,.4);hormone.name=mode+'-signal';g.add(hormone);}
